import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  random,
  spring,
  Easing,
} from '../remotionShim';
import { Circle } from "@remotion/shapes";
import { evolvePath } from "@remotion/paths";

// Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Helper Functions ---

// Smoothstep for smoother boundary transitions than linear interpolation
const smoothstep = (min: number, max: number, value: number) => {
  const x = Math.max(0, Math.min(1, (value - min) / (max - min)));
  return x * x * (3 - 2 * x);
};

// Calculates the vertical boundary of the pipe at a given X position
// Returns the Y value of the TOP boundary relative to center
const getPipeBoundaryOffset = (x: number, width: number) => {
  const centerSectionStart = width * 0.35;
  const centerSectionEnd = width * 0.65;
  const transitionLength = width * 0.1;

  const wideOffset = 180; // Half-height of wide section
  const narrowOffset = 60; // Half-height of narrow section

  // Left wide section
  if (x < centerSectionStart) return wideOffset;
  
  // Transition to narrow
  if (x < centerSectionStart + transitionLength) {
    const progress = (x - centerSectionStart) / transitionLength;
    // Use smoothstep for organic curve
    const t = progress * progress * (3 - 2 * progress);
    return wideOffset - (wideOffset - narrowOffset) * t;
  }

  // Narrow section
  if (x < centerSectionEnd - transitionLength) return narrowOffset;

  // Transition to wide
  if (x < centerSectionEnd) {
    const progress = (x - (centerSectionEnd - transitionLength)) / transitionLength;
    const t = progress * progress * (3 - 2 * progress);
    return narrowOffset + (wideOffset - narrowOffset) * t;
  }

  // Right wide section
  return wideOffset;
};

// --- Schema ---



export type BottleneckExplainerProps = Record<string, any>;

const BottleneckExplainer: React.FC<BottleneckExplainerProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 10,
  titleText = "Operation bottleneck is the downfall of all companies",
  particleColor = "#ef5350",
  pipeColor = "#333333",
  arrowColor = "#9e9e9e",
  particleCount = 60,
}) => {
  useFontLoader(["Roboto"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Layout Constants ---
  const centerY = height * 0.55;
  const pipePathStrokeWidth = 3;
  
  // Calculate Pipe Paths
  const pipePathData = useMemo(() => {
    // Generate SVG path string matching the getPipeBoundaryOffset logic
    const steps = 40; // Resolution of curve
    let topPath = `M 0 ${centerY - getPipeBoundaryOffset(0, width)} `;
    let bottomPath = `M 0 ${centerY + getPipeBoundaryOffset(0, width)} `;

    for (let i = 1; i <= steps; i++) {
      const x = (width / steps) * i;
      const offset = getPipeBoundaryOffset(x, width);
      topPath += `L ${x} ${centerY - offset} `;
      bottomPath += `L ${x} ${centerY + offset} `;
    }
    return { top: topPath, bottom: bottomPath };
  }, [width, centerY]);

  // --- Animations ---

  // Title Animation
  const titleOpacity = interpolate(frame, [0, 30], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, 30], [50, 0], {
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  // Pipe Draw Animation
  const pipeEvolution = spring({
    frame: frame - 10,
    fps,
    config: { damping: 200, stiffness: 100 },
    durationInFrames: 60,
  });
  
  const topPipeEvolved = evolvePath(pipeEvolution, pipePathData.top);
  const bottomPipeEvolved = evolvePath(pipeEvolution, pipePathData.bottom);

  // Particles Logic
  const particles = useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => {
      // Seed random based on index
      const seed = i * 123.45; 
      const startOffset = random(seed) * (durationInSeconds * fps * 0.7); // Spread start times
      const lane = random(seed + 1); // 0 to 1, relative vertical position
      const size = 20 + random(seed + 2) * 10;
      return { id: i, startOffset, lane, size };
    });
  }, [particleCount, durationInSeconds, fps]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Roboto, sans-serif",
      }}
    >
      {/* Title */}
      <div
        style={{
          position: "absolute",
          top: "10%",
          width: "100%",
          textAlign: "center",
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
          padding: "0 10%",
          zIndex: 10,
        }}
      >
        <h1
          style={{
            color: pipeColor,
            fontSize: "48px",
            fontWeight: 700,
            lineHeight: 1.3,
            margin: 0,
          }}
        >
          {titleText}
        </h1>
      </div>

      {/* Pipe Lines */}
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", top: 0, left: 0, zIndex: 1 }}
      >
        <path
          d={pipePathData.top}
          stroke={pipeColor}
          strokeWidth={pipePathStrokeWidth}
          fill="none"
          strokeDasharray={topPipeEvolved.strokeDasharray}
          strokeDashoffset={topPipeEvolved.strokeDashoffset}
        />
        <path
          d={pipePathData.bottom}
          stroke={pipeColor}
          strokeWidth={pipePathStrokeWidth}
          fill="none"
          strokeDasharray={bottomPipeEvolved.strokeDasharray}
          strokeDashoffset={bottomPipeEvolved.strokeDashoffset}
        />
        
        {/* Arrows (Left Input) */}
        {[0, 1, 2].map((i) => (
           <path
             key={`arrow-left-${i}`}
             d={`M ${width * 0.05} ${centerY - 120 + i * 120} L ${width * 0.15} ${centerY - 120 + i * 120}`}
             stroke={arrowColor}
             strokeWidth={4}
             markerEnd="url(#arrowhead)"
             opacity={interpolate(frame - i * 10, [0, 20], [0, 1], { extrapolateRight: 'clamp' })}
           />
        ))}
         {/* Arrow (Right Output) */}
         <path
             d={`M ${width * 0.85} ${centerY} L ${width * 0.95} ${centerY}`}
             stroke={arrowColor}
             strokeWidth={4}
             markerEnd="url(#arrowhead)"
             opacity={interpolate(frame - 50, [0, 20], [0, 1], { extrapolateRight: 'clamp' })}
           />

        <defs>
          <marker
            id="arrowhead"
            markerWidth="10"
            markerHeight="7"
            refX="9"
            refY="3.5"
            orient="auto"
          >
            <polygon points="0 0, 10 3.5, 0 7" fill={arrowColor} />
          </marker>
        </defs>
      </svg>

      {/* Particles Container */}
      <AbsoluteFill style={{ zIndex: 2 }}>
        {particles.map((p) => {
          const t = frame - p.startOffset;
          if (t < 0) return null;

          // Velocity Map: Fast -> Slow -> Fast
          // We map 't' (time) to 'x' (position) non-linearly to simulate density changes
          // 0-30%: Fast traverse of first 30% of width
          // 30-70%: Slow traverse of middle 40% (Bottleneck)
          // 70-100%: Fast traverse of exit
          
          const totalFrames = 250; // frames to cross screen
          const progress = t / totalFrames;
          
          if (progress > 1.1) return null; // Off screen

          // Custom easing to create the "Jam" effect
          // Steeper slope = faster speed. Flatter slope = slower speed.
          // We want fast entrance (steep), slow middle (flat), fast exit (steep)
          // Input: progress (0-1). Output: Screen X percentage (0-1)
          const xProgress = interpolate(
            progress,
            [0, 0.35, 0.65, 1], // Time keyframes
            [0, 0.45, 0.55, 1], // Position keyframes (Notice how little position changes between 0.35 and 0.65)
            { extrapolateRight: "extend" }
          );

          const x = xProgress * width;
          
          // Calculate available Y space at this X
          const yBoundary = getPipeBoundaryOffset(x, width);
          const padding = p.size / 2 + 10;
          const maxOffset = Math.max(0, yBoundary - padding);
          
          // Map lane (0-1) to valid Y range
          // -1 to 1 range
          const laneCentered = (p.lane - 0.5) * 2; 
          const yOffset = laneCentered * maxOffset;
          const y = centerY + yOffset;

          // Entrance Fade
          const opacity = interpolate(t, [0, 10], [0, 1], { extrapolateRight: 'clamp' });
          // Exit Fade
          const exitOpacity = interpolate(progress, [0.95, 1], [1, 0], { extrapolateRight: 'clamp' });

          return (
            <div
              key={p.id}
              style={{
                position: "absolute",
                left: x - p.size / 2,
                top: y - p.size / 2,
                opacity: opacity * exitOpacity,
              }}
            >
              <Circle
                radius={p.size / 2}
                fill={`${particleColor}33`} // Transparent fill
                stroke={particleColor}
                strokeWidth={3}
              />
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default BottleneckExplainer;